function groupBy(items, keyFn) {
  const out = {};
  for (const item of items) {
    const k = keyFn(item);
    (out[k] ||= []).push(item);
  }
  return out;
}

seed_examples.tests:
const assert = require('assert');
assert.deepStrictEqual(groupBy([1, 2, 3, 4], n => (n % 2 ? 'odd' : 'even')), { odd: [1, 3], even: [2, 4] });
assert.deepStrictEqual(groupBy([], x => x), {});

