function debounceCalls(times, wait) {
  const fired = [];
  for (let i = 0; i < times.length; i++) {
    const next = times[i + 1];
    if (next === undefined || next - times[i] >= wait) fired.push(times[i] + wait);
  }
  return fired;
}

seed_examples.tests:
const assert = require('assert');
assert.deepStrictEqual(debounceCalls([0, 50, 100, 400], 200), [300, 600]);
assert.deepStrictEqual(debounceCalls([], 100), []);
assert.deepStrictEqual(debounceCalls([0, 300], 100), [100, 400]);
